// Нормалізація вхідного + перевірка нічного вікна (Europe/Kyiv 22:00–08:00)
const body = $input.item.json.body || $input.item.json;

const channel     = body.channel || 'unknown';   // telegram | whatsapp | instagram | phone
const contact     = body.contact || body.from || '';
const contactName = body.name || '';
const text        = body.text || body.message || '';

// Час у Києві — єдине джерело часу для всього флоу
const now  = new Date();
const kyiv = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Kyiv' }));
const p    = (x) => String(x).padStart(2, '0');
const nowKyiv = `${kyiv.getFullYear()}-${p(kyiv.getMonth()+1)}-${p(kyiv.getDate())} `
              + `${p(kyiv.getHours())}:${p(kyiv.getMinutes())} (Europe/Kyiv)`;

const hour = kyiv.getHours();
const isNightWindow = (hour >= 22 || hour < 8);

// Ручний прапорець зміни. УВАГА: $env у Code-нодах заблокований за замовчуванням —
// щоб прапорець працював, у docker-compose n8n треба N8N_BLOCK_ENV_ACCESS_IN_NODE=false
let shiftFlag = 'auto';
try { if ($env && $env.MARIA_SHIFT) shiftFlag = $env.MARIA_SHIFT; } catch (e) { /* доступ закрито */ }
// force_shift у тілі запиту — для тестування вдень. У проді не передавати.
const force = body.force_shift;
const shiftActive = force === true  ? true
                  : force === false ? false
                  : shiftFlag === 'on'  ? true
                  : shiftFlag === 'off' ? false
                  : isNightWindow;

return [{ json: { channel, contact, contactName, text, hour, nowKyiv, nowIso: now.toISOString(), shiftActive } }];

// Агент повертає JSON. Витягуємо його стійко до обгорток і зайвого тексту.
const raw = String($json.output ?? $json.text ?? '').trim();

let parsed = null;
const fence = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
const candidate = fence ? fence[1] : raw;
try { parsed = JSON.parse(candidate); } catch (e) {
  const m = candidate.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
}

const norm = { 'вирішено':'resolved', 'в роботі':'in-progress', 'needs-you':'needs-you',
               'resolved':'resolved', 'in-progress':'in-progress' };

// Модель не віддала JSON — не втрачаємо звернення: віддаємо текст як є і кличемо людину.
if (!parsed || typeof parsed !== 'object' || !parsed.reply) {
  return [{ json: {
    reply:  raw || 'Вибачте, сталася технічна помилка. Передаю звернення денному диспетчеру.',
    topic:  'не розібрано',
    action: 'відповідь не вдалося структурувати',
    status: 'needs-you',
    link:   '',
    parseFailed: true,
  }}];
}

return [{ json: {
  reply:  String(parsed.reply),
  topic:  String(parsed.topic  || '—'),
  action: String(parsed.action || '—'),
  status: norm[String(parsed.status || '').toLowerCase().trim()] || 'needs-you',
  link:   String(parsed.link   || '—'),
  parseFailed: false,
}}];
